replace.new:
raw = []
for line in evidence_archive.iter_evidence(evidence_path):
    try:
        _r = json.loads(line)
    except Exception:
        continue
    # v3.0 hourly reset: pre-v3 hourly rows carried a mispriced p_yes and
    # are quarantined from tree learning too (see learning.HOURLY_SIG_V_MIN).
    if str(_r.get("base_cell", "")).startswith("hourly|"):
        try:
            if int(_r.get("sig_v") or 1) < learning.HOURLY_SIG_V_MIN:
                continue
        except (TypeError, ValueError):
            continue
    raw.append(_r)
